        "Форми: er bringt, brachte, hat gebracht. Обично има две дополнувања: кому? (датив) и што? (акузатив): Er bringt mir das Buch.",
        "И „донесува“ и „однесува“ на германски се bringen; насоката ја покажува контекстот или предлогот (zu, nach)."
