        "Се менува како определениот член der: номинатив dieser/diese/dieses, акузатив diesen (машки род), датив diesem/dieser/diesem. Во множина: diese, diesen. Формата за среден род dieses Jahr значи „оваа година“.",
        "Dieser се користи и наместо именка, со падежна наставка, кога е јасно за што станува збор: Dieser gefällt mir (овој ми се допаѓа)."
