        "Er kommt erst morgen значи „тој ќе дојде дури утре“. За разлика од nur (обично ограничување), erst нагласува дека нешто сѐ уште не се случило или не стигнало до одредено време.",
        "Не го мешај со erste (прв), кој е реден број."
