        "Форми: legt, legte, hat gelegt (правилен). Повратно: sich legen — легнува: Ich lege mich ins Bett. Понекогаш и „несе (јајца)”: Die Henne legt Eier.",
        "Разлика од liegen: legen изразува дејство (накаде?), liegen — состојба (каде?): Ich lege das Buch auf den Tisch, но Das Buch liegt auf dem Tisch."
