      "explanation": [
        "Главна идеја: sehen значи „види” — со очите забележува што има наоколу или пред себе. Глаголот е силен: ich sehe, du siehst, er sieht (e се менува во ie), минато sah, Perfekt hat gesehen.",
        "Обично се додава објект во акузатив: Ich sehe einen Hund. Со sich, sich sehen значи да се сретнат или да се видат еден со друг: Wir sehen uns morgen.",
        "Кога се гледа свесно, подолго или во нешто определено, обично се користи schauen или ansehen; sehen почесто го изразува самиот факт на гледањето."
      ],
