      "explanation": [
        "Главна идеја: sie е лична заменка за 3. лице. Во еднина значи таа (sie ist), во множина — тие (sie sind). Наставката на глаголот покажува кое од двете се мисли: sie kommt (таа) и sie kommen (тие).",
        "Падежи: акузатив sie (ich sehe sie), датив во еднина ihr, во множина ihnen. Ако се зборува за предмет со член од женски род, и тој може да се замени со sie: die Tasche – sie.",
        "Sie со голема буква (Sie) е учтивото „Вие”; на почетокот од реченицата разликата ја покажуваат содржината и формата на глаголот."
      ],
      "examples": [
        {
          "de": "Sie ist meine Lehrerin.",
          "lv": "Таа е мојата наставничка."
        },
        {
          "de": "Sie wohnen in Riga.",
          "lv": "Тие живеат во Рига."
        },
        {
          "de": "Ich sehe sie jeden Tag.",
          "lv": "Ја гледам секој ден."
        },
        {
          "de": "Sie sind noch zu Hause.",
          "lv": "Тие сѐ уште се дома."
        },
        {
          "de": "Ich gebe ihr das Buch.",
          "lv": "Јас ѝ ја давам книгата."
        }
      ],
      "comparison": [
        {
          "word": "er",
          "meaning": "тој",
          "example": "Er arbeitet. – Тој работи."
        },
        {
          "word": "es",
          "meaning": "тоа",
          "example": "Es regnet. – Врне."
        },
        {
          "word": "Sie",
          "meaning": "Вие (учтиво)",
          "example": "Wie heißen Sie? – Како се викате?"
        }
      ],
      "tip": [
        "Гледај го глаголот: sie macht = таа прави, sie machen = тие прават.",
        "Запомни го дативот: ihr (нејзе) и ihnen (ним)."
      ],
