        "Прашањето е Wie ist das Wetter? Чести споеви: gutes/schlechtes Wetter (убаво/лошо време), der Wetterbericht (временска прогноза).",
        "Македонското „време” може да значи и временски услови и време како поим; во германскиот тоа се два различни збора: das Wetter и die Zeit."
